sp_widget.css:
.tm-patient-strip { display:flex; align-items:center; gap:16px;
.tm-avatar-lg { width:56px; height:56px; border-radius:50%; object-fit:cover; }
.tm-strip-body { flex:1; h3 { margin:0 0 4px; font-size:18px; } p { margin:0; font-size:13px; } } }

sp_widget.script:
(function() {
data.found = false;
var id = $sp.getParameter('sys_id') || $sp.getParameter('patient');
if (!id) return;
var gr = new GlideRecord('x_trackmed_patient');
if (!gr.get(id)) return; // ACLs apply: get() fails if not readable
data.found = true;
data.sys_id = gr.getUniqueValue();
data.name = gr.getValue('first_name') + ' ' + gr.getValue('last_name');
data.dob = gr.getDisplayValue('date_of_birth');
data.gender = gr.getDisplayValue('gender');
data.phone = gr.getValue('phone');
data.status = gr.getValue('status');
data.photo = gr.user ? '/profile_image.do?sys_id=' + gr.getValue('user') : '';
data.canEdit = gr.canWrite();
})();
